if __name__ == "__main__":
    base = os.path.dirname(os.path.abspath(__file__))
    allp = []
    for job, j in JOBS.items():
        d = f"{base}/{job}"; os.makedirs(f"{d}/img", exist_ok=True); os.makedirs(f"{d}/aud", exist_ok=True)
        sc = [dict(text=s["text"], mood=s["mood"], elements=s["el"]) for s in j["scenes"]]
        json.dump(dict(title=j["title"], music_seed=j["music_seed"], scenes=sc), open(f"{d}/scenes.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        for k, s in enumerate(j["scenes"]):
            allp.append(dict(job=job, n=k + 1, ref=s["img"][0], prompt=s["img"][1], vo=s["text"]))
    json.dump(allp, open(f"{base}/../../xabash_prompts.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(len(allp), "prompts")
